//! Server-side source highlighting: a port of Rouge, the highlighter the
//! reference Asciidoctor uses for `source-highlighter=rouge`.
//!
//! Rouge is MIT licensed (see `LICENSE-rouge`); its lexer rules, themes and
//! formatter behavior are reproduced from the pinned version in
//! `compatibility/rouge-version`, partly generated by
//! `scripts/generate_rouge.rb`. No Ruby code runs here.

pub mod adapter;
pub mod format;
pub mod guess;
pub mod lexer;
mod lexers;
pub mod regex;
pub mod theme;
pub mod token;

mod generated {
    #[rustfmt::skip]
    pub(crate) mod lexers;
    #[rustfmt::skip]
    pub(crate) mod themes;
    #[rustfmt::skip]
    pub(crate) mod tokens;
}
